-- 039 — the migration surveys, their answer options, and every district figure in both rounds.
--
-- SOURCE.
--
-- The Rural Development and Migration Commission (Palayan Ayog), Pauri Garhwal, surveyed
-- every gram panchayat in the state twice. Its reports are PDFs, so this is a `manual`
-- source in the same sense as the transcribed reservoir figures (HYD-7): a human read the
-- tables and typed them, and the row records which document and which round.
--
-- HOW THESE NUMBERS WERE CHECKED.
--
-- Every district figure below appears in TWO independently typeset reports — the 2018
-- English report, and the 2023 report which reprints the 2018 round beside its own. All four
-- headline counts reconcile across both, and the per-district columns sum to the state
-- totals the reports state for themselves (383,726 and 118,981 for 2018; 307,310 and 28,531
-- for 2022). The share dimensions each sum to 100.00 per district, and the village condition
-- counts sum to the stated state totals (734 emptied, 482 of them without a road, and so on).
--
-- ONE DISCREPANCY, RECORDED RATHER THAN RESOLVED.
--
-- The 2023 report's prose says 28,631 people migrated permanently between 2018 and 2022; its
-- own tables say 28,531, and those columns add up. The table figure is used here. The prose
-- figure is noted so that a reader who finds it in the PDF is not left thinking this is wrong.

   access_method, cadence, may_redistribute, metadata_status, metadata_note, is_enabled)
VALUES
  (
    'uk-migration-commission',
    'migration',
    'Rural Development and Migration Commission, Uttarakhand',
    'ग्राम्य विकास एवं पलायन निवारण आयोग, उत्तराखण्ड',
    'https://palayanayog.uk.gov.in',
    'Rural Development and Migration Commission (Palayan Ayog), Uttarakhand, Pauri Garhwal',
    'Government of Uttarakhand report, reproduced with attribution.',
    'manual',
    'static',
    TRUE,
    'provisional',
    'Transcribed by hand from the commission''s published PDF reports; there is no feed. Two rounds so far: an interim report of April 2018 covering 2008-2018, and a second interim report of February 2023 covering 2018 to September 2022. Figures were cross-checked against both documents and against the state totals each report states for itself. The 2023 report''s prose gives permanent migration as 28,631 where its tables give 28,531; the table figure is stored.',
    TRUE
  )
ON CONFLICT (source_key) DO UPDATE SET
  owner_module     = EXCLUDED.owner_module,
  department_en    = EXCLUDED.department_en,
  department_hi    = EXCLUDED.department_hi,
  url              = EXCLUDED.url,
  attribution      = EXCLUDED.attribution,
  licence          = EXCLUDED.licence,
  access_method    = EXCLUDED.access_method,
  cadence          = EXCLUDED.cadence,
  may_redistribute = EXCLUDED.may_redistribute,
  metadata_status  = EXCLUDED.metadata_status,
  metadata_note    = EXCLUDED.metadata_note,
  is_enabled       = EXCLUDED.is_enabled;

   gram_panchayats_surveyed, blocks_surveyed, source_id, evidence_url)
VALUES
